ALTER TYPE pairing_admin_capability ADD VALUE IF NOT EXISTS 'PUBLISH_START_LIST';
ALTER TYPE audit_actor_kind ADD VALUE IF NOT EXISTS 'START_LIST_PUBLICATION_ACCESS_CREDENTIAL';
ALTER TABLE pairing_admin_access_credential ADD CONSTRAINT pairing_admin_start_list_publication_lifetime_check CHECK (capability::text <> 'PUBLISH_START_LIST' OR expires_at <= issued_at + interval '8 hours');
CREATE TABLE start_list_publication (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL, race_id uuid NOT NULL REFERENCES race(id), actor_credential_id uuid NOT NULL REFERENCES pairing_admin_access_credential(id), revision integer NOT NULL, action text NOT NULL, intent jsonb NOT NULL, source_snapshot_version integer NOT NULL, source_hash text, content jsonb, decided_at timestamptz NOT NULL, CONSTRAINT start_list_publication_revision_check CHECK (revision > 0 AND source_snapshot_version > 0), CONSTRAINT start_list_publication_action_check CHECK (action IN ('PUBLISH','WITHDRAW')), CONSTRAINT start_list_publication_intent_check CHECK (jsonb_typeof(intent) = 'object'), CONSTRAINT start_list_publication_payload_check CHECK ((action='PUBLISH' AND source_hash IS NOT NULL AND source_hash ~ '^[a-f0-9]{64}$' AND content IS NOT NULL AND jsonb_typeof(content)='object') OR (action='WITHDRAW' AND source_hash IS NULL AND content IS NULL)));
CREATE UNIQUE INDEX start_list_publication_request_uidx ON start_list_publication(request_id); CREATE UNIQUE INDEX start_list_publication_race_revision_uidx ON start_list_publication(race_id, revision); CREATE INDEX start_list_publication_race_revision_idx ON start_list_publication(race_id, revision DESC); CREATE TRIGGER start_list_publication_immutable BEFORE UPDATE OR DELETE ON start_list_publication FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
